--- src/greet.ts	
+++ src/greet.ts	
@@ -0,0 +1,7 @@
+// PI-CORE-001 / DD-CORE-002: greet 纯函数，两分支，零副作用
+export function greet(name: string): string {
+  if (name === "") {
+    return "Hello, world!";
+  }
+  return "Hello, " + name + "!";
+}

